verification.proof_script:
from qiskit.circuit.library import (efficient_su2, excitation_preserving, pauli_two_design,
                                    quantum_volume, real_amplitudes, zz_feature_map)

builders = {
    "A": ("efficient_su2(3)", lambda: efficient_su2(3)),
    "B": ("zz_feature_map(3)", lambda: zz_feature_map(3)),
    "C": ("pauli_two_design(3, seed=7)", lambda: pauli_two_design(3, seed=7)),
    "D": ("quantum_volume(3, seed=7)", lambda: quantum_volume(3, seed=7)),
    "E": ("real_amplitudes(3)", lambda: real_amplitudes(3)),
    "F": ("excitation_preserving(3)", lambda: excitation_preserving(3)),
}
target = {"ry", "cx"}
evidence = {}
proven = []
observed = {}
for k, (label, fn) in builders.items():
    circ = fn()
    ops = {g: int(v) for g, v in circ.count_ops().items()}
    observed[label] = ops
    m = bool(set(ops) == target)
    evidence[k] = (f"built {label}: the executed circuit contains {ops} with"
                   f" {int(circ.num_parameters)} free parameters"
                   f" -> gate set is exactly ry plus cx? {m}")
    if m:
        proven.append(k)
emit_verdict({"answer": proven, "evidence": evidence, "observed": observed})
